function aircraftBadge(name){
 const n=name.toUpperCase(),prop=/ATR|DHC|DASH|SAAB|TWIN OTTER|ISLANDER/.test(n),jumbo=/747|380|340/.test(n),regional=/EMBRAER|ERJ|CRJ|DASH|DHC|ATR/.test(n),long=/777|350|330|787|767/.test(n),hump=/747/.test(n),deck=/380/.test(n),tTail=/CRJ|ERJ|DASH|DHC/.test(n),wide=jumbo||long;
 const palette=prop?['#d27035','#f4c968']:jumbo?['#77528c','#e3b3cf']:regional?['#278b7c','#b9db97']:long?['#347bad','#b7d9e9']:['#c45865','#f0bba2'];
 const length=jumbo?145:long?140:regional?117:128,top=101-length/2,bottom=101+length/2,wing=jumbo?78:long?71:prop?57:60,wingY=jumbo?99:prop?94:101;
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 220 220');svg.setAttribute('aria-hidden','true');
 const shape=(tag,attrs)=>{const el=document.createElementNS(svg.namespaceURI,tag);for(const [key,value]of Object.entries(attrs))el.setAttribute(key,value);svg.append(el);return el;};
 shape('circle',{cx:110,cy:110,r:99,fill:'none',stroke:'#ffffff55','stroke-width':1});shape('circle',{cx:110,cy:110,r:89,fill:'none',stroke:'#ffffff26','stroke-width':1,'stroke-dasharray':'2 7'});
 shape('path',{d:`M110 ${top+42} L${110-wing} ${wingY+15} L${110-wing+3} ${wingY+26} L110 ${wingY+4} L${110+wing-3} ${wingY+26} L${110+wing} ${wingY+15} Z`,fill:'#f3eedc',stroke:'#ffffff','stroke-width':1.5});
 const engines=jumbo?[-1,-.52,.52,1]:[-.62,.62];for(const pos of engines){const x=110+pos*wing*.69,y=wingY-(prop?3:8);shape('rect',{x:x-5,y,width:10,height:prop?19:26,rx:5,fill:'#d6e3df',stroke:'#ffffff','stroke-width':1});shape('path',{d:`M${x-3} ${y+4} L${x+3} ${y+4}`,stroke:'#6d8b8d','stroke-width':2});if(prop){shape('path',{d:`M${x-12} ${y+2} L${x+12} ${y+2} M${x} ${y-9} L${x} ${y+13}`,stroke:'#244e54','stroke-width':3,'stroke-linecap':'round'});}}
 shape('path',{d:`M110 ${top} C${wide?119:116} ${top+6} 119 ${top+19} 117 ${bottom-24} L110 ${bottom} L103 ${bottom-24} C101 ${top+19} ${wide?101:104} ${top+6} 110 ${top}Z`,fill:'#fff9e8',stroke:'#fff','stroke-width':1.5});
 shape('path',{d:`M110 ${bottom-32} L${tTail?81:86} ${bottom-9} L${tTail?84:88} ${bottom-4} L110 ${bottom-15} L${tTail?136:132} ${bottom-4} L${tTail?139:134} ${bottom-9}Z`,fill:'#e9efdf',stroke:'#fff','stroke-width':1});
 shape('path',{d:`M106 ${top+15} Q110 ${top+12}114 ${top+15} L113 ${top+19} L107 ${top+19}Z`,fill:'#315962'});
 if(hump)shape('path',{d:`M106 ${top+24} Q110 ${top+20}114 ${top+24} L114 ${top+49} Q110 ${top+54}106 ${top+49}Z`,fill:'#ecd6b2',stroke:'#fff','stroke-width':1});
 if(deck)for(const x of [106,114])shape('path',{d:`M${x} ${top+26}L${x} ${bottom-28}`,stroke:'#c7b896','stroke-width':1.7,'stroke-dasharray':'2 4'});
 const trail=shape('path',{d:`M110 ${bottom+5}L110 ${Math.min(195,bottom+18)}`,stroke:'#ffffff55','stroke-width':1.5,'stroke-dasharray':'3 3'});
 return {svg,palette,description:prop?'螺旋桨客机':jumbo?'四发客机':regional?'支线喷气客机':'双发喷气客机'};
}

'use strict';
const fleetPage=document.createElement('section');fleetPage.className='fleet-page';fleetPage.hidden=true;fleetPage.innerHTML='<div class="fleet-heading"><div><h2>我的机型收藏册</h2><p id="fleet-count"></p></div><input type="search" id="fleet-search" placeholder="搜索机型" aria-label="搜索机型"></div><p id="fleet-missing"></p><div class="fleet-grid" id="fleet-grid"></div>';document.querySelector('main').append(fleetPage);
const fleetNav=document.createElement('button');fleetNav.type='button';fleetNav.dataset.view='fleet';fleetNav.textContent='机型收藏册';document.querySelector('.view-links').append(fleetNav);
const fleetDialog=document.createElement('dialog');fleetDialog.className='flight-dialog';fleetDialog.innerHTML='<div class="dialog-heading"><h2 id="fleet-detail-title"></h2><button type="button" class="dialog-close" id="fleet-close" aria-label="关闭">×</button></div><div id="fleet-detail"></div>';document.body.append(fleetDialog);$('fleet-close').onclick=()=>fleetDialog.close();
function fleetKey(value){return String(value||'').trim().replace(/\s+/g,' ');}
function fleetGroups(){const groups=new Map();let missing=0;for(const r of state.rows||[]){const date=dateValue(r.date);if(!date||date>localDate()||recordCanceled(r))continue;const name=fleetKey(r.aircraft);if(!name){missing++;continue;}const key=name.toLowerCase();if(!groups.has(key))groups.set(key,{name,rows:[]});groups.get(key).rows.push(r);}return {groups:[...groups.values()].sort((a,b)=>b.rows.length-a.rows.length||a.name.localeCompare(b.name)),missing};}
function fleetSpecial(name){return /\b(?:a?380|b?747)(?:\b|[- ])/i.test(name)||(!/airbus|boeing|\b[ab][2378]\d\d/i.test(name));}
function fleetDetail(g){$('fleet-detail-title').textContent=g.name;const box=$('fleet-detail');box.replaceChildren();for(const r of [...g.rows].sort((a,b)=>dateValue(b.date).localeCompare(dateValue(a.date)))){const row=document.createElement('div');row.className='fleet-leg';const title=document.createElement('strong');title.textContent=`${recordAirportName(r.from)} → ${recordAirportName(r.to)}`;const sub=document.createElement('span');sub.textContent=`${dateValue(r.date)} · ${normalizeAirlineCode(r.airline)} ${r.flight||''} · ${airportCode(r.from)} → ${airportCode(r.to)}`;row.append(title,sub);box.append(row);}fleetDialog.showModal();}
function renderFleet(){const {groups,missing}=fleetGroups(),query=$('fleet-search').value.trim().toLowerCase();$('fleet-count').textContent=`已收藏 ${groups.length} 种机型 · ${groups.reduce((n,g)=>n+g.rows.length,0)} 次飞行`;$('fleet-missing').textContent=missing?`${missing} 条历史行程尚未填写机型，可在航班记录中补齐。`:'';const box=$('fleet-grid');box.replaceChildren();for(const g of groups.filter(g=>g.name.toLowerCase().includes(query))){const button=document.createElement('button');button.type='button';button.className='fleet-card';const art=aircraftBadge(g.name);button.style.setProperty('--badge-color',art.palette[0]);button.style.setProperty('--badge-light',art.palette[1]);const icon=document.createElement('div');icon.className='fleet-icon';icon.append(art.svg);button.title=g.name+' · '+art.description+'（示意图）';const title=document.createElement('h3');title.textContent=g.name;const detail=document.createElement('p');const airlines=new Set(g.rows.map(r=>normalizeAirlineCode(r.airline)).filter(Boolean)),routes=new Set(g.rows.map(r=>[airportCode(r.from),airportCode(r.to)].join('→')));detail.textContent=`${g.rows.length} 次飞行`;button.title+=` · ${airlines.size} 家航司 · ${routes.size} 条单向航线`;const dates=g.rows.map(r=>dateValue(r.date)).sort();const first=document.createElement('small');first.textContent=`首次乘坐 ${dates[0]}`;const tag=document.createElement('span');tag.className='fleet-tag';tag.textContent=fleetSpecial(g.name)?'特别收藏':'已打卡';button.append(icon,tag,title,detail,first);button.onclick=()=>fleetDetail(g);box.append(button);}if(!box.children.length){const empty=document.createElement('p');empty.textContent=groups.length?'没有匹配的机型。':'添加已飞行且填写了机型的航班，开启你的收藏册。';box.append(empty);}}
const originalShowWorkspace=showWorkspace;showWorkspace=function(view){originalShowWorkspace(view==='fleet'?'records':view);fleetPage.hidden=view!=='fleet';if(view==='fleet'){records.hidden=true;workspace.hidden=true;$('workspace-title').textContent='每一种飞机，一段新的记忆。';$('workspace-description').textContent='从历史行程中收集你乘坐过的机型。';document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view==='fleet')b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});renderFleet();}};
fleetNav.onclick=()=>showWorkspace('fleet');$('fleet-search').oninput=renderFleet;window.addEventListener('atlas:rows',renderFleet);renderFleet();
